import { throwGlobalError } from '~adapters/helpers/error';
import { getJSON } from '~adapters/helpers/request';
import { BranchParameters } from '../types/branch-like';
import { ComponentQualifier, TreeComponent, TreeComponentWithPath } from '../types/component';
import { Paging } from '../types/paging';

export type GetTreeParams = {
  asc?: boolean;
  component: string;
  p?: number;
  ps?: number;
  q?: string;
  s?: string;
  strategy?: 'all' | 'leaves' | 'children';
} & BranchParameters;

export function getTree<
  T extends TreeComponent = TreeComponent,
  Base extends TreeComponent = TreeComponent,
>(
  data: GetTreeParams & { qualifiers?: string },
): Promise<{ baseComponent: Base; components: T[]; paging: Paging }> {
  return getJSON('/api/components/tree', data).catch(throwGlobalError);
}

export function getFiles<
  T extends TreeComponentWithPath = TreeComponentWithPath,
  Base extends TreeComponent = TreeComponent,
>(data: GetTreeParams) {
  return getTree<T, Base>({ ...data, qualifiers: ComponentQualifier.File });
}

export function getDirectories<
  T extends TreeComponentWithPath = TreeComponentWithPath,
  Base extends TreeComponent = TreeComponent,
>(data: GetTreeParams) {
  return getTree<T, Base>({
    ...data,
    qualifiers: ComponentQualifier.Directory,
  });
}
